SELECT ca.ca_state, c.c_preferred_cust_flag, SUM(cr.cr_return_amount) AS total_return_amount, AVG(cr.cr_return_quantity) AS avg_return_quantity FROM catalog_returns cr JOIN customer c ON cr.cr_refunded_customer_sk = c.c_customer_sk JOIN customer_address ca ON cr.cr_refunded_addr_sk = ca.ca_address_sk WHERE cr.cr_returned_date_sk = 2451041 AND c.c_birth_year = 1945 GROUP BY ca.ca_state, c.c_preferred_cust_flag
